import pdfplumber
import pandas as pd
import json
import numpy as np

def extract_pdf_data(pdf_path):
    employees = {}
    with pdfplumber.open(pdf_path) as pdf:
        for i, page in enumerate(pdf.pages):
            tables = page.extract_tables()
            for table in tables:
                for row in table:
                    if not row:
                        continue
                    # Check if header
                    if row[0] == "ID":
                        continue

                    # Assuming strict column order: ID, First, Last, Dept, Position, Salary, Years, Location, Score
                    # Handle potential None values or bad rows
                    if len(row) < 9:
                        continue

                    emp_id = row[0]
                    if not emp_id.startswith("EMP"):
                        continue

                    try:
                        salary_str = str(row[5]).replace(',', '')
                        salary = int(salary_str)
                        years = int(row[6])
                        score = float(row[8])
                    except ValueError:
                        continue # Skip rows with bad number formats

                    employees[emp_id] = {
                        "ID": emp_id,
                        "First": row[1],
                        "Last": row[2],
                        "Dept": row[3],
                        "Position": row[4],
                        "Salary": salary,
                        "Years": years,
                        "Location": row[7],
                        "Score": score
                    }
    return employees

def extract_excel_data(xlsx_path):
    df = pd.read_excel(xlsx_path)
    employees = {}
    for _, row in df.iterrows():
        emp_id = row['ID']
        employees[emp_id] = {
            "ID": emp_id,
            "First": row['First'],
            "Last": row['Last'],
            "Dept": row['Dept'],
            "Position": row['Position'],
            "Salary": int(row['Salary']),
            "Years": int(row['Years']),
            "Location": row['Location'],
            "Score": float(row['Score'])
        }
    return employees

def compare_data(pdf_data, excel_data):
    deleted = []
    modified = []

    # Check for deleted (in PDF but not in Excel)
    for emp_id in pdf_data:
        if emp_id not in excel_data:
            deleted.append(emp_id)

    # Check for modifications (in both, but different)
    for emp_id, old_record in pdf_data.items():
        if emp_id in excel_data:
            new_record = excel_data[emp_id]
            # Compare fields
            fields_to_compare = ["First", "Last", "Dept", "Position", "Salary", "Years", "Location", "Score"]
            for field in fields_to_compare:
                old_val = old_record[field]
                new_val = new_record[field]

                # Loose comparison for strings (strip whitespace)
                if isinstance(old_val, str) and isinstance(new_val, str):
                    if old_val.strip() != new_val.strip():
                        modified.append({
                            "id": emp_id,
                            "field": field,
                            "old_value": old_val,
                            "new_value": new_val
                        })
                # Comparison for numbers (handle float precision)
                elif isinstance(old_val, float) or isinstance(new_val, float):
                    if abs(old_val - new_val) > 0.001:
                         modified.append({
                            "id": emp_id,
                            "field": field,
                            "old_value": old_val,
                            "new_value": new_val
                        })
                else:
                    if old_val != new_val:
                        modified.append({
                            "id": emp_id,
                            "field": field,
                            "old_value": old_val,
                            "new_value": new_val
                        })

    return deleted, modified

def main():
    pdf_path = '/root/employees_backup.pdf'
    xlsx_path = '/root/employees_current.xlsx'
    output_path = '/root/diff_report.json'

    print("Extracting PDF data...")
    pdf_data = extract_pdf_data(pdf_path)
    print(f"Extracted {len(pdf_data)} records from PDF.")

    print("Extracting Excel data...")
    excel_data = extract_excel_data(xlsx_path)
    print(f"Extracted {len(excel_data)} records from Excel.")

    print("Comparing data...")
    deleted_ids, modified_records = compare_data(pdf_data, excel_data)

    # Sort results
    deleted_ids.sort()
    modified_records.sort(key=lambda x: x['id'])

    report = {
        "deleted_employees": deleted_ids,
        "modified_employees": modified_records
    }

    with open(output_path, 'w') as f:
        json.dump(report, f, indent=2)

    print(f"Report generated at {output_path}")

if __name__ == "__main__":
    main()
